class Solution {
  public int minOperations(int[] nums, int sum) {
    int INF = Integer.MAX_VALUE / 2;
    int[] dp = new int[sum + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int x : nums) {
      int[] bestCost = new int[sum + 1];
      java.util.Arrays.fill(bestCost, INF);
      // all multiplications come before divisions, so a value is either x * 2^c or floor(x / 2^c)
      for (int c = 0; ((long) x << c) <= sum; c++) bestCost[x << c] = Math.min(bestCost[x << c], c);
      for (int c = 1; (x >> c) > 0; c++)
        if ((x >> c) <= sum) bestCost[x >> c] = Math.min(bestCost[x >> c], c);
      int[] nd = dp.clone();
      for (int val = 1; val <= sum; val++) {
        if (bestCost[val] >= INF) continue;
        for (int s = sum; s >= val; s--) {
          if (dp[s - val] < INF) nd[s] = Math.min(nd[s], dp[s - val] + bestCost[val]);
        }
      }
      dp = nd;
    }
    return dp[sum] >= INF ? -1 : dp[sum];
  }
}
